SET XACT_ABORT ON;
BEGIN TRANSACTION;
CREATE TABLE dbo.WholesalePurchasePlans(Id bigint IDENTITY PRIMARY KEY,PlanNumber varchar(32) NOT NULL UNIQUE,SourceRequestId bigint NOT NULL,SourceRequestVersionId bigint NOT NULL,Status varchar(32) NOT NULL,AssignedBuyerStaffId bigint NULL,PurchaseCostCny decimal(18,2) NULL,PackagingCostCny decimal(18,2) NOT NULL DEFAULT 0,SampleCostCny decimal(18,2) NOT NULL DEFAULT 0,DomesticShippingCny decimal(18,2) NOT NULL DEFAULT 0,InternationalShippingCny decimal(18,2) NOT NULL DEFAULT 0,OtherCostCny decimal(18,2) NOT NULL DEFAULT 0,TotalCostCny decimal(18,2) NULL,CnyPerUsd decimal(18,6) NULL,TotalCostUsd decimal(18,2) NULL,ProfitRate decimal(8,4) NULL,FinalQuoteUsd decimal(18,2) NULL,CreatedByStaffId bigint NOT NULL,ApprovedByStaffId bigint NULL,ApprovedAtUtc datetime2(3) NULL,CreatedAtUtc datetime2(3) NOT NULL DEFAULT SYSUTCDATETIME(),UpdatedAtUtc datetime2(3) NOT NULL DEFAULT SYSUTCDATETIME(),RowVersion rowversion);
CREATE TABLE dbo.WholesalePlanItems(Id bigint IDENTITY PRIMARY KEY,PlanId bigint NOT NULL REFERENCES dbo.WholesalePurchasePlans(Id),SourceRequestItemId bigint NULL,ProductKey varchar(64) NOT NULL,ProductName nvarchar(255) NOT NULL,Quantity decimal(18,3) NOT NULL,Unit nvarchar(30) NOT NULL,BuyerStaffId bigint NULL,PurchaseUnitPriceCny decimal(18,4) NULL,SnapshotJson nvarchar(max) NOT NULL,CreatedAtUtc datetime2(3) NOT NULL DEFAULT SYSUTCDATETIME(),UpdatedAtUtc datetime2(3) NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT UX_WholesalePlanItems UNIQUE(PlanId,ProductKey));
CREATE TABLE dbo.WholesaleSuppliers(Id bigint IDENTITY PRIMARY KEY,Name nvarchar(255) NOT NULL,Code varchar(50) NULL,ContactJson nvarchar(max) NULL,Status varchar(20) NOT NULL,CreatedAtUtc datetime2(3) NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE dbo.WholesaleCandidateProducts(Id bigint IDENTITY PRIMARY KEY,PlanItemId bigint NOT NULL,SupplierId bigint NULL,Name nvarchar(255) NOT NULL,ReferenceUrl nvarchar(1000) NULL,SpecificationJson nvarchar(max) NULL,Status varchar(20) NOT NULL,CreatedAtUtc datetime2(3) NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE dbo.WholesaleInquiries(Id bigint IDENTITY PRIMARY KEY,PlanItemId bigint NOT NULL,SupplierId bigint NOT NULL,UnitPriceCny decimal(18,4) NULL,Moq decimal(18,3) NULL,LeadDays int NULL,ValidUntil date NULL,Terms nvarchar(1000) NULL,CreatedAtUtc datetime2(3) NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE dbo.WholesaleSamples(Id bigint IDENTITY PRIMARY KEY,PlanItemId bigint NOT NULL,SupplierId bigint NULL,Status varchar(24) NOT NULL,CostCny decimal(18,2) NOT NULL DEFAULT 0,TrackingNumber nvarchar(100) NULL,Notes nvarchar(1000) NULL,UpdatedAtUtc datetime2(3) NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE dbo.WholesalePlanFiles(Id bigint IDENTITY PRIMARY KEY,PlanId bigint NOT NULL,PlanItemId bigint NULL,FileAssetId bigint NOT NULL,Category varchar(40) NOT NULL,IsCustomerVisible bit NOT NULL DEFAULT 0,CreatedAtUtc datetime2(3) NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE dbo.WholesaleQuoteApprovals(Id bigint IDENTITY PRIMARY KEY,PlanId bigint NOT NULL,Status varchar(24) NOT NULL,QuoteUsd decimal(18,2) NOT NULL,ProfitRate decimal(8,4) NOT NULL,SubmittedByStaffId bigint NOT NULL,DecidedByStaffId bigint NULL,DecisionNote nvarchar(1000) NULL,SubmittedAtUtc datetime2(3) NOT NULL DEFAULT SYSUTCDATETIME(),DecidedAtUtc datetime2(3) NULL);
CREATE TABLE dbo.WholesaleMailTasks(Id bigint IDENTITY PRIMARY KEY,PlanId bigint NOT NULL,ApprovalId bigint NOT NULL,TemplateCode varchar(120) NOT NULL,Recipient nvarchar(320) NOT NULL,Status varchar(24) NOT NULL DEFAULT 'Pending',PayloadJson nvarchar(max) NOT NULL,CreatedAtUtc datetime2(3) NOT NULL DEFAULT SYSUTCDATETIME(),SentAtUtc datetime2(3) NULL);
CREATE INDEX IX_WholesalePurchasePlans_StatusBuyer ON dbo.WholesalePurchasePlans(Status,AssignedBuyerStaffId);
COMMIT TRANSACTION;
